def last_digit_factorial_division(a, b):
    if a > b:
        return 0
    if a == b:
        return 1
    # If b >= 10, factorial(b) ends with 0, so result ends with 0
    if b >= 10:
        return 0
    # Compute factorial(b) // factorial(a) = product of numbers from a+1 to b
    result = 1
    for i in range(a + 1, b + 1):
        result *= i
    return result % 10

