def next_smallest_palindrome(num):
    num = str(num)
    length = len(num)
    if set(num) == {'9'}:
        return int('1' + ('0' * (length - 1)) + '1')
    half = length // 2
    left = num[:half]
    middle = num[half] if length % 2 else ''
    right = num[half + (1 if length % 2 else 0):]
    if int(right[::-1]) > int(left):
        if length % 2:
            middle = str(int(middle) + 1) if middle != '9' else '0'
            if middle == '0':
                left = str(int(left) + 1)
        else:
            left = str(int(left) + 1)
    palindrome = left + middle + left[::-1]
    if int(palindrome) <= int(num):
        if length % 2:
            if middle == '9':
                left = str(int(left) + 1)
                middle = '0'
            else:
                middle = str(int(middle) + 1)
        else:
            left = str(int(left) + 1)
        palindrome = left + middle + left[::-1]
    return int(palindrome)

